    true_jaemin: { title: '밥은 먹었어요? — 매일의 대답', rank: 'S', bg: 'han_river', c: 'jaemin', e: 'laugh',
      t: '브랜드전략팀은 올해의 팀상을 2년 연속 받았고, 윤재민 팀장은 사내 최초로 “칼퇴 팀장상”이라는 이상한 상도 받았다. 그는 이제 하루 네 잔의 커피를 마시고 일곱 시간을 잔다. 부모님께는 명절마다 각각 다른 날 찾아가겠다고 먼저 말했고, 두 분 다 “그래라”라고 했다. 매일 점심, 두 사람 중 누가 먼저 “밥은 먹었어요?”라고 묻는지 내기를 한다. 진 사람이 저녁을 산다. 대부분 편의점 라면이다. 계란은 두 개.' },
