    secret_gyeol: { title: '결재란에 내 이름을 — 결 스튜디오', rank: 'SS', bg: 'office_floor', c: 'taeo', e: 'smile',
      t: '이듬해 3월 2일, 결 스튜디오가 문을 열었다. 초대 브랜드 디렉터 {name}, 입사 1년 차. 전략은 윤재민, 기술은 루프랩 한시우, 크리에이티브는 IAN&CO 차이안, 그리고 이사회 의장석에는 강태오가 앉았다. 첫 출근날, 나는 1층 카페에서 아메리카노 여섯 잔을 샀다. 이번엔 한 잔도 쏟지 않았다. 사무실 벽에는 수첩의 세 문장이 걸렸다. “쓸수록 내 손 모양이 되는 물건. 물려받는 브랜드. 물려주는 브랜드.” 그리고 네 사람이 동시에 물었다. “그래서, 누구랑 점심 먹을 거예요?” — 이야기는 이제 막 시작이다.' },
