    blurb: '입사 첫날, 엘리베이터에서 본부장에게 아메리카노를 쏟았다. 한결그룹 브랜드전략팀 신입 {name}의 1년 — 얼음 본부장, 다정한 팀장, 비밀 많은 연하 개발자, 그리고 경쟁사 대표까지. 매각 위기의 브랜드 “결”을 지키는 동안, 누구의 결재 서류에 서명하게 될까?',
    cover: { bg: 'office_floor', c: 'taeo', e: 'cold' },
    world: '무대는 현대 서울 광화문의 한결타워. 한결그룹은 재계 20위권 대기업으로, 계열사 한결리빙의 오래된 생활용품 브랜드 “결”(나무 도마, 주걱 등)이 매출 부진으로 해외 펀드 하버캐피털에 매각될 위기에 있다. 주인공 {name}는 3월에 브랜드전략본부 브랜드전략팀에 입사한 신입 사원(여성)으로, 1년 동안 수습에서 첫 대형 프로젝트까지 성장한다. 본부장 강태오는 강성진 회장의 막내아들로 “결”을 만든 돌아가신 어머니 때문에 브랜드를 지키려 아버지와 싸우고, 팀장 윤재민은 과로하는 다정한 상사, 한시우는 경쟁 스타트업 루프랩의 정체를 숨긴 계약직 개발자, 차이안은 경쟁 에이전시 IAN&CO의 대표로 7년 전 한결에 아이디어를 빼앗긴 과거가 있다. 마케팅본부 최동혁 부장은 브랜드전략팀을 해체해 흡수하려 하며 뒤에서 방해한다. 절친한 사수 박소라는 사내 가십의 여왕이다. 한 해는 입사 첫날 커피 사고, 강릉 워크숍, 회식과 야근, IAN&CO와의 경쟁 PT, 도쿄 출장, 사내 루머, 합병·매각 위기, 연말 시상식으로 흘러간다. 분위기는 설레고 유쾌한 오피스 로맨스이며, 직장 내 선과 존중을 지키는 건전한 연애를 그린다.',
